using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using PhoneStore.Core.Contracts;
internal sealed partial class QaSuite
{
    async Task DiscoveryHomeBeforeSales(){
        await Check("WEB-HOME-EMPTY","Trang chủ riêng và header khách","Không bộ lọc; fallback đúng nhãn; một link đăng nhập",async()=>{using var response=await anon.Get("/");var html=System.Net.WebUtility.HtmlDecode(await response.Content.ReadAsStringAsync());Assert(response.IsSuccessStatusCode&&!html.Contains("name=\"BrandId\"")&&!html.Contains("name=\"MinPrice\""));Assert(html.Contains("Khám phá sản phẩm")&&!html.Contains("Sản phẩm bán chạy"));var header=html[..html.IndexOf("</header>")];Assert(header.Contains("Trang chủ")&&header.Contains("Sản phẩm")&&!header.Contains("Đăng ký"));Assert(header.Split("/Account/Login").Length==2);using var login=await anon.Get("/Account/Login");Assert((await login.Content.ReadAsStringAsync()).Contains("Chưa có tài khoản?"));});
    }
    async Task Discovery(){
        await Check("WEB-COLOR","Màu/dung lượng/giá cùng một biến thể","Không ghép chéo, card giá đúng biến thể",async()=>{var v=await Fixture(5,2);var p=await ProductFor(v[0].Id);var prefix="/api/catalog?Query="+p.Code+"&Color="+Uri.EscapeDataString(v[0].Color);Assert((await anon.Read<Page<ProductDto>>(prefix+"&StorageGb="+v[1].StorageGb)).Total==0);var matched=await anon.Read<Page<ProductDto>>(prefix+"&StorageGb="+v[0].StorageGb+"&MinPrice=1000000&MaxPrice=1000000");Assert(matched.Total==1&&matched.Items[0].Variants.Single().Id==v[0].Id);using var page=await anon.Get("/Search?Query="+p.Code+"&Color="+Uri.EscapeDataString(v[0].Color));Assert((await page.Content.ReadAsStringAsync()).Contains("Màu sắc"));});
        await Check("WEB-SUGGESTIONS","Gợi ý dữ liệu DB/rỗng/biên/ký tự lạ","i có iPhone; tối đa8; rỗng không quét danh mục",async()=>{Assert((await anon.Read<List<SearchSuggestion>>("/api/suggestions?query=")).Count==0);var suggestions=await anon.Read<List<SearchSuggestion>>("/api/suggestions?query=i");Assert(suggestions.Count is >0 and <=8&&suggestions.Any(x=>x.Label.Contains("iPhone")));Assert(suggestions[0].Label.StartsWith("i",StringComparison.OrdinalIgnoreCase));Assert((await anon.Read<List<SearchSuggestion>>("/api/suggestions?query=IPHONE")).Any(x=>x.Label.Contains("iPhone")));Assert((await anon.Read<List<SearchSuggestion>>("/api/suggestions?query="+Uri.EscapeDataString("' OR 1=1;--"))).Count==0);await Status(await anon.Get("/api/suggestions?query="+new string('x',101)),400);});
        await Check("WEB-ACCENTS","Tìm tiếng Việt không dấu, loại hàng ngừng bán","anh duong khớp Ánh Dương; ngừng bán không gợi ý",async()=>{var v=(await Fixture(5))[0];var p=await ProductFor(v.Id);await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{Name="Ánh Dương"},HttpMethod.Put),200);Assert((await anon.Read<Page<ProductDto>>("/api/catalog?Query=anh%20duong")).Items.Any(x=>x.Id==p.Id));Assert((await anon.Read<List<SearchSuggestion>>("/api/suggestions?query=anh%20duong")).Any(x=>x.Label=="Ánh Dương"));p=await ProductFor(v.Id);await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{Active=false},HttpMethod.Put),200);Assert(!(await anon.Read<List<SearchSuggestion>>("/api/suggestions?query=anh%20duong")).Any(x=>x.Label=="Ánh Dương"));});
        await Check("WEB-GALLERY","Ảnh HTTPS bổ sung, thứ tự và public DTO","Lưu/sắp ảnh đúng; HTTP bị từ chối; không lộ kho nội bộ",async()=>{var v=(await Fixture(5))[0];var p=await ProductFor(v.Id);var input=Input(p) with{Images=[new("https://example.test/image-b.jpg",3),new("https://example.test/image-a.jpg",1)]};await Status(await admin.Send($"/api/admin/products/{p.Id}",input,HttpMethod.Put),200);var actual=await anon.Read<ProductDto>($"/api/catalog/{p.Id}");Assert(actual.Images?.Select(x=>x.SortOrder).SequenceEqual(new[]{1,3})==true);p=await ProductFor(v.Id);await Status(await admin.Send($"/api/admin/products/{p.Id}",Input(p) with{Images=[new("http://example.test/no.jpg",0)]},HttpMethod.Put),400);using var response=await anon.Get($"/api/catalog/{p.Id}");var body=JsonDocument.Parse(await response.Content.ReadAsStringAsync()).RootElement;var variant=body.GetProperty("variants")[0];Assert(!variant.TryGetProperty("reserved",out _)&&!variant.TryGetProperty("onHand",out _)&&!variant.TryGetProperty("version",out _));});
        await Check("WEB-QR","QR trực tiếp bị chặn, COD còn hoạt động","400, không thêm đơn/giữ/thanh toán QR; COD200",async()=>{var v=(await Fixture(5))[0];var req=await Cart(a,[v]);int before;await using(var db=Open())before=await db.Orders.CountAsync();using var response=await a.Send("/api/orders",req with{PaymentMethod="QR"});Assert((int)response.StatusCode==400&&JsonDocument.Parse(await response.Content.ReadAsStringAsync()).RootElement.GetProperty("message").GetString()!.Contains("QR"));await using(var db=Open()){Assert(await db.Orders.CountAsync()==before);Assert((await db.Stock.SingleAsync(x=>x.VariantId==v.Id)).Reserved==0);}var order=await Place(a,req);Assert(order.Payment=="CHUA_THU");await Move(order.Id,"cancel");});
        await Check("WEB-BESTSELLERS","Bán chạy tính tay: gộp biến thể, loại trạng thái/kỳ, tie-break","B100sp/300tr trước A100sp/160tr; không đếm hủy/chờ/cũ",async()=>{
            var av=await Fixture(250,2,1000000m);var bv=(await Fixture(250,price:3000000m))[0];var cv=(await Fixture(250,price:100000m))[0];var pa=await ProductFor(av[0].Id);var pb=await ProductFor(bv.Id);var pc=await ProductFor(cv.Id);
            async Task<OrderDto> Order(List<(VariantDto V,int Q)> lines){await Clear(a);foreach(var line in lines)await Status(await a.Send("/api/cart",new CartInput(line.V.Id,line.Q)),200);var cart=await a.Read<CartDto>("/api/cart");return await Place(a,new(Guid.NewGuid(),"Người nhận báo cáo","0909999999","Địa chỉ kiểm thử báo cáo",cart.Lines.Select(x=>new PriceConfirmation(x.VariantId,x.Quantity,x.Price)).ToList()));}
            async Task Complete(long id){await Move(id,"confirm");await Move(id,"dispatch");await Move(id,"complete");}
            var oa=await Order([(av[0],40),(av[1],60)]);await Complete(oa.Id);var ob=await Order([(bv,100)]);await Complete(ob.Id);var canceled=await Order([(av[0],150)]);await Move(canceled.Id,"cancel");await Order([(bv,80)]);var old=await Order([(cv,200)]);await Complete(old.Id);await using(var db=Open())await db.Orders.Where(x=>x.Id==old.Id).ExecuteUpdateAsync(s=>s.SetProperty(x=>x.CompletedAt,DateTime.UtcNow.AddDays(-31)));
            var ranked=await anon.Read<List<ProductDto>>("/api/bestsellers");Assert(ranked.Count<=8&&ranked[0].Id==pb.Id&&ranked[1].Id==pa.Id&&ranked.Count(x=>x.Id==pa.Id)==1&&!ranked.Any(x=>x.Id==pc.Id));
            pa=await ProductFor(av[0].Id);await Status(await admin.Send($"/api/admin/products/{pa.Id}",Input(pa) with{Variants=Input(pa).Variants.Select(x=>x.Id==av[0].Id?x with{Price=9000000m}:x).ToList()},HttpMethod.Put),200);ranked=await anon.Read<List<ProductDto>>("/api/bestsellers");Assert(ranked.Single(x=>x.Id==pa.Id).Variants.Min(x=>x.Price)==2000000m);
        });
    }
}
